package com.civic.controller; import com.civic.dto.DepartmentRequest; import com.civic.entity.Department; import com.civic.repository.DepartmentRepository; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/departments") @RequiredArgsConstructor public class DepartmentController {private final DepartmentRepository repo; @GetMapping public List<Department> all(){return repo.findByActiveTrueOrderByNameAsc();} @PostMapping @PreAuthorize("hasRole('SUPER_ADMIN')") public Department create(@RequestBody DepartmentRequest r){if(repo.existsByNameIgnoreCase(r.name()))throw new RuntimeException("Department already exists");return repo.save(Department.builder().name(r.name().trim()).build());} @PutMapping("/{id}") @PreAuthorize("hasRole('SUPER_ADMIN')") public Department update(@PathVariable Long id,@RequestBody DepartmentRequest r){Department d=repo.findById(id).orElseThrow(()->new RuntimeException("Department not found"));d.setName(r.name().trim());return repo.save(d);} @DeleteMapping("/{id}") @PreAuthorize("hasRole('SUPER_ADMIN')") public void delete(@PathVariable Long id){Department d=repo.findById(id).orElseThrow(()->new RuntimeException("Department not found"));d.setActive(false);repo.save(d);} }
